            this.fbox(cx + 4, 11.20 + 0.55, chiefZ - 1.4, 0.9, 0.95, 0.9, col3(0x1a1a1a));

            // Staircase 3: Floor 3 -> Rooftop Helipad
            addStairs(stairX, bldgZ2 - 16, 11.20, 16.80, 12.0, 3.2, 0.28);

            // =========================================================================
