            statusBar.innerHTML = `<span>Health: <b id="gta-food-hp" style="color:#ff3b30;">${curHp}%</b> · Cash: <b id="gta-food-cash" style="color:#39ff88;">${curMoney}</b></span><span style="color:#71849a;">Press [Esc] to exit</span>`;
